<Modal>
  {#if show}<span>{message}</span>{/if}
  {#each items as item}<b>{item}</b>{/each}
</Modal>
<script>
  import Modal from './Modal.html';
  export default {
    components: { Modal },
    data() { return { show: false, message: 'first', items: [] }; }
  };
</script>
\`);

